import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Cuttle Out the Middleman Direct Shard Access in Erasure Coded Poolsmp4","description":"","frontmatter":{"title":"Cuttle Out the Middleman Direct Shard Access in Erasure Coded Poolsmp4","date":"2026-07-10T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","Erasure Coding","性能优化","OSD","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Cuttle_Out_the_Middleman_Direct_Shard_Access_in_Erasure_Coded_Poolsmp4.md","filePath":"posts/2026/Cuttle_Out_the_Middleman_Direct_Shard_Access_in_Erasure_Coded_Poolsmp4.md","lastUpdated":null}'),l={name:"posts/2026/Cuttle_Out_the_Middleman_Direct_Shard_Access_in_Erasure_Coded_Poolsmp4.md"};function o(s,a,d,n,c,p){return r(),t("div",null,[...a[0]||(a[0]=[i('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由 Alex Enskow 主讲，他曾深度参与 Fast EC（Erasure Coding）开发工作历时约两年。本次分享介绍了 Erasure Coding 读路径的下一阶段演进：<strong>Direct Reads</strong>（直接分片访问），核心思想是客户端绕过 primary OSD，直接向持有数据的 OSD 发起读请求，从而大幅降低延迟、减少网络数据传输量。</p><h2 id="传统-erasure-coding-读路径的问题" tabindex="-1">传统 Erasure Coding 读路径的问题 <a class="header-anchor" href="#传统-erasure-coding-读路径的问题" aria-label="Permalink to &quot;传统 Erasure Coding 读路径的问题&quot;">​</a></h2><h3 id="小读-small-reads" tabindex="-1">小读（Small Reads） <a class="header-anchor" href="#小读-small-reads" aria-label="Permalink to &quot;小读（Small Reads）&quot;">​</a></h3><p>在传统 EC 读路径中：</p><ol><li>客户端向 primary OSD 发送读请求</li><li>primary OSD 发现数据不在本地，转发请求至实际持有数据的 OSD</li><li>该 OSD 返回数据给 primary OSD</li><li>primary OSD 再将数据转发给客户端</li></ol><p><strong>问题：</strong></p><ul><li>消息数量：4 条消息</li><li>数据传输量：请求 16K 数据实际传输 32K（两跳导致双倍流量）</li><li>延迟：4 个消息传输时间单位（tick）</li></ul><h3 id="大读-large-reads" tabindex="-1">大读（Large Reads） <a class="header-anchor" href="#大读-large-reads" aria-label="Permalink to &quot;大读（Large Reads）&quot;">​</a></h3><p>对于 256K 大读场景：</p><ol><li>客户端请求 primary OSD</li><li>primary OSD 并行向多个 OSD 发送读请求</li><li>各 OSD 返回数据</li><li>primary OSD 汇聚数据后返回客户端</li></ol><p><strong>问题：</strong></p><ul><li>消息数量：6 条</li><li>数据传输量：请求 256K 实际网络传输约 512K</li><li>延迟：4 个 tick</li></ul><h2 id="direct-reads-方案原理" tabindex="-1">Direct Reads 方案原理 <a class="header-anchor" href="#direct-reads-方案原理" aria-label="Permalink to &quot;Direct Reads 方案原理&quot;">​</a></h2><h3 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h3><p>客户端已持有完整的 cluster map（OSD map），并且知道 EC pool 的 K 值和 stripe unit 大小，因此可以<strong>精确计算出数据分布在哪些 OSD 上</strong>，直接向目标 OSD 发起读请求。</p><h3 id="小读优化效果" tabindex="-1">小读优化效果 <a class="header-anchor" href="#小读优化效果" aria-label="Permalink to &quot;小读优化效果&quot;">​</a></h3><ul><li>消息数量减少 50%（从 4 条降至 2 条）</li><li>网络传输数据量减少 50%</li><li>延迟减少 50%（从 4 tick 降至 2 tick）</li></ul><h3 id="大读优化效果" tabindex="-1">大读优化效果 <a class="header-anchor" href="#大读优化效果" aria-label="Permalink to &quot;大读优化效果&quot;">​</a></h3><ul><li>客户端计算出所有分片位置，并行向多个 OSD 发送请求</li><li>消息数量与传统方式相近，但数据不再经过 primary 中转</li><li>网络传输量降低约 50%</li><li>延迟显著降低，CPU 开销也因减少了 primary OSD 的转发处理而降低</li></ul><h2 id="性能测试结果" tabindex="-1">性能测试结果 <a class="header-anchor" href="#性能测试结果" aria-label="Permalink to &quot;性能测试结果&quot;">​</a></h2><h3 id="对比说明" tabindex="-1">对比说明 <a class="header-anchor" href="#对比说明" aria-label="Permalink to &quot;对比说明&quot;">​</a></h3><ul><li><strong>蓝线</strong>：传统 EC 读路径</li><li><strong>绿线</strong>：Direct Reads（EC）</li><li><strong>红线</strong>：Replica（均衡读，balanced reads 开启）</li></ul><h3 id="小读场景" tabindex="-1">小读场景 <a class="header-anchor" href="#小读场景" aria-label="Permalink to &quot;小读场景&quot;">​</a></h3><p>Direct Reads 使 EC 的读性能与 replica 几乎持平，达成了重要目标：在小 IO 下 EC 不再明显弱于 replica。</p><h3 id="大读场景" tabindex="-1">大读场景 <a class="header-anchor" href="#大读场景" aria-label="Permalink to &quot;大读场景&quot;">​</a></h3><p>EC Direct Reads 在带宽和延迟上均有显著提升，在 4MB 读场景（RADOS 典型最大读取单位）下，EC Direct Reads 的性能甚至<strong>优于 replica</strong>，原因在于：</p><ul><li>EC 的 K 值更高，数据分散在更多 OSD/磁盘上，CRUSH 算法的负载均衡效果更好</li><li>replica 在超大读时，单个 OSD 的数据量过大，随机分布开始失效，出现热点</li></ul><h3 id="性能曲线分析-对数坐标图" tabindex="-1">性能曲线分析（对数坐标图） <a class="header-anchor" href="#性能曲线分析-对数坐标图" aria-label="Permalink to &quot;性能曲线分析（对数坐标图）&quot;">​</a></h3><p>演讲者分析了从小 IO 到大 IO 的完整性能曲线变化规律：</p><ol><li><strong>读 IO 落在单 OSD 上时</strong>：Direct Reads 与 replica 性能相当</li><li><strong>IO 大小超过 stripe unit 时</strong>：出现性能拐点，需要跨多 OSD，消息数增加，CPU 成为瓶颈</li><li><strong>更大 IO</strong>：随着每条消息携带更多数据，带宽逐渐追上 replica</li><li><strong>超大 IO（趋于磁盘限制）</strong>：EC 因 K 值高、盘数多，plateau 持续时间更长，整体优于 replica</li></ol><p><strong>关键结论：在任何 IO 大小下，绿线（Direct Reads）从不低于蓝线（传统 EC），性能只增不减。</strong></p><h2 id="stripe-unit-调优建议" tabindex="-1">Stripe Unit 调优建议 <a class="header-anchor" href="#stripe-unit-调优建议" aria-label="Permalink to &quot;Stripe Unit 调优建议&quot;">​</a></h2><p>演讲者提出了一个调优方向：将 stripe unit 调大至 256K，使得大多数读 IO 都落在&quot;小于 stripe unit&quot;的区间，从而最大化 Direct Reads 的性能收益，理论上可接近 replica 性能。</p><p><strong>警告</strong>：</p><blockquote><p>大 stripe unit 对读友好，但对<strong>写</strong>不友好，会引入额外开销。</p></blockquote><p>适用场景建议：</p><ul><li>读多写少（如 90% 以上读负载）</li><li>纯 RBD pool 场景（RBD 的 IO 模式与大 stripe unit 更匹配）</li></ul><h2 id="osd-故障时的降级处理" tabindex="-1">OSD 故障时的降级处理 <a class="header-anchor" href="#osd-故障时的降级处理" aria-label="Permalink to &quot;OSD 故障时的降级处理&quot;">​</a></h2><p>当某个 OSD 不可用时：</p><ol><li>客户端通过 cluster map 感知到该 OSD 下线</li><li>将对应 shard 的读请求<strong>回退至 primary OSD</strong></li><li>primary OSD 执行 recovery 重建该 shard 数据后返回</li></ol><p><strong>注意事项：</strong></p><ul><li>存在少量 transient failure 情况：客户端发送请求到 OSD 后，OSD 返回&quot;数据未就绪&quot;，此时请求回退到 primary</li><li>这类回退在正常运行时极为罕见，只在 PG splitting 或 OSD 故障时频率上升</li></ul><h2 id="数据一致性保证" tabindex="-1">数据一致性保证 <a class="header-anchor" href="#数据一致性保证" aria-label="Permalink to &quot;数据一致性保证&quot;">​</a></h2><p>演讲者强调 Direct Reads 提供以下一致性保证：</p><ol><li><strong>不会返回未完成写入的数据</strong>：若某次写操作中止且未重试，该写涉及的数据永远不会被读出</li><li><strong>不会返回 torn read</strong>：若写操作进行中，部分 OSD 已更新、部分未更新，客户端检测到版本不一致时，会自动通过 primary 重试，避免读到撕裂数据（torn read），即**读一致性（read consistency）**保证</li></ol><h2 id="如何启用-direct-reads" tabindex="-1">如何启用 Direct Reads <a class="header-anchor" href="#如何启用-direct-reads" aria-label="Permalink to &quot;如何启用 Direct Reads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>客户端类型</th><th>启用方式</th></tr></thead><tbody><tr><td>RBD</td><td>开启已有的 <code>balance_reads</code> 配置项</td></tr><tr><td>CephFS</td><td>挂载选项中设置 <code>read_policy=balance</code></td></tr><tr><td>全局（RGW/RBD/CephFS 统一）</td><td>在配置文件中设置 <code>read_policy = balance</code></td></tr></tbody></table><p><strong>长期目标</strong>：将 Direct Reads 设为所有客户端的默认行为，因为该功能<strong>不存在性能损耗，只有性能提升</strong>。</p><p><strong>当前状态</strong>：Umbrella（Ceph 下一版本）中已实现，Teuthology 测试中发现少量与旧特性（legacy features）相关的 bug，正在修复中，暂未写入主文档。</p><h2 id="replica-的大读优化-延伸" tabindex="-1">Replica 的大读优化（延伸） <a class="header-anchor" href="#replica-的大读优化-延伸" aria-label="Permalink to &quot;Replica 的大读优化（延伸）&quot;">​</a></h2><p>演讲者还提到了将类似思路应用于 replica 的大读场景：</p><ul><li>对于超大读，客户端将读请求拆分为多个子读，分别直接发送给不同 replica OSD</li><li>虽然消息数增加，但每条消息传输数据量减少，整体延迟有所降低</li><li>在 CPU 非瓶颈的大 IO 场景下，带宽和延迟均有小幅改善</li></ul><h2 id="q-a-摘录" tabindex="-1">Q&amp;A 摘录 <a class="header-anchor" href="#q-a-摘录" aria-label="Permalink to &quot;Q&amp;A 摘录&quot;">​</a></h2><p><strong>Q：回退到 primary 的频率有没有监控指标？</strong></p><p>A：目前演讲者尚未专门测量，理论上应该非常罕见。最常见的触发场景是&quot;uncommitted write&quot;——有写 IO 在途时客户端无法直接读取，但这种情况每个 PG 每次最多只影响一个 object，且持续时间极短。在 PG splitting 或 OSD 故障期间频率会显著上升。后来有听众指出 Ceph 中已有相关 performance metric，演讲者表示之前没注意到该指标。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Direct Reads 是 Ceph Erasure Coding 读路径的重大优化，通过让客户端直接访问数据所在 OSD，消除了 primary OSD 的中转开销。在保持数据一致性（无 torn read、无 uncommitted data 泄漏）的前提下：</p><ul><li>小读：EC 性能达到与 replica 相当的水平</li><li>大读：EC 性能在延迟和带宽上均可超越 replica</li><li>启用无代价：对所有读场景无负面影响</li></ul>',59)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
